seq=''
with open('region.fasta') as f:
    for line in f:
        if not line.startswith('>'):
            seq+=line.strip()
seq=seq.upper(); L=len(seq)

code = {
 'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L',
 'ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V',
 'TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
 'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
 'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
 'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
 'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
 'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}

# Minus-strand ORFs: find 'CAT' (anticodon of ATG) in original seq; read leftward.
def translate_minus(start):  # start is 1-based pos of 'C' in CAT (rightmost base)
    aa=[]
    p = start          # position of 3rd base of anticodon (rightmost)
    # codon occupies [p-2, p-1, p] in original; complement-reverse = ATG
    while p-3 >= 0:
        codon = seq[p-3:p]
        a = code[codon]
        if a=='*': break
        aa.append(a)
        p -= 3
    return ''.join(aa), p  # p = position where stop codon's rightmost base is (0-based = p-1)

def translate_plus(start):  # start = 1-based pos of A in ATG
    aa=[]
    i=start-1
    while i+3<=L:
        a=code[seq[i:i+3]]
        if a=='*': break
        aa.append(a); i+=3
    return ''.join(aa), i+3   # i+3 = 1-based end of stop (exclusive)

# Find all canonical ORFs
canon=[]
# Plus strand
for i in range(L-2):
    if seq[i:i+3]=='ATG':
        p,end = translate_plus(i+1)
        if len(p)>=30: canon.append(('+', i+1, end, len(p), p))
# Minus strand
for p in range(2, L):
    if seq[p-1:p+2]=='CAT':   # 0-based p-1 is index of 'C'; 1-based pos = p
        pr,end = translate_minus(p)
        if len(pr)>=30: canon.append(('-', p, end, len(pr), pr))

canon.sort(key=lambda x:-x[3])
